// Official legacy GitHub wordmark, https://github-media-downloads.s3.amazonaws.com/GitHub-Logos.zip
const github =
  "data:image/png;base64,";

export function PricingBrandmarks() {
  const ordered = ["Vercel", "Clerk", "Resend", "OpenAI", "GitHub", "Anthropic"];
  return (
    <ul className="rp-brandmarks" aria-label="Customer logos">
      {ordered.map((name) => {
        if (name === "GitHub")
          return (
            <li key={name}>
              <span
                style={{
                  display: "block",
                  position: "relative",
                  width: 55.34375,
                  height: 15,
                  overflow: "hidden",
                }}
              >
                <img
                  src={github}
                  alt="GitHub"
                  style={{
                    position: "absolute",
                    maxWidth: "none",
                    width: 64.1026,
                    height: 26.2821,
                    left: -4.2949,
                    top: -5.4487,
                  }}
                />
              </span>
            </li>
          );
        const mark = marks.find((item) => item.name === name)!;
        return (
          <li key={name}>
            <img
              src={`data:image/svg+xml,${encodeURIComponent(mark.svg)}`}
              alt={mark.name}
              width={mark.width}
              height={mark.height}
              style={{
                display: "block",
                width: mark.width,
                height: mark.height,
                objectFit: "contain",
              }}
            />
          </li>
        );
      })}
    </ul>
  );
}
